package ai.intentoms.platform.ids;

import java.security.SecureRandom;
import java.util.UUID;

/** Time-ordered UUIDv7 identifiers (index-friendly in PostgreSQL) plus short ids for keys and codes. */
public final class Ids {
    private static final SecureRandom RANDOM = new SecureRandom();
    private static final char[] ALPHABET = "0123456789abcdefghjkmnpqrstvwxyz".toCharArray();

    private Ids() {}

    private static long lastMs;
    private static int counter; // 12-bit rand_a, RFC 9562 §6.2 method 1: monotonic within one millisecond

    /** Monotonic UUIDv7: ids generated by one JVM are strictly increasing even within the same millisecond. */
    public static UUID uuid7() {
        long ms = System.currentTimeMillis();
        int seq;
        synchronized (Ids.class) {
            if (ms > lastMs) {
                lastMs = ms;
                counter = RANDOM.nextInt(1 << 11); // start low so the counter has room before rolling over
            } else {
                ms = lastMs;
                if (++counter >= (1 << 12)) { // counter exhausted: borrow the next millisecond
                    counter = RANDOM.nextInt(1 << 11);
                    lastMs = ++ms;
                }
            }
            seq = counter;
        }
        byte[] rnd = new byte[8];
        RANDOM.nextBytes(rnd);
        long msb = (ms << 16) | 0x7000L | (seq & 0x0FFF);
        long lsb = 0;
        for (int i = 0; i < 8; i++) lsb = (lsb << 8) | (rnd[i] & 0xFF);
        lsb = (lsb & 0x3FFFFFFFFFFFFFFFL) | 0x8000000000000000L;
        return new UUID(msb, lsb);
    }

    public static String id() { return uuid7().toString(); }

    /** 12-char Crockford base32 id; used for API key ids, RMA numbers, correlation ids. */
    public static String shortId() {
        char[] out = new char[12];
        for (int i = 0; i < out.length; i++) out[i] = ALPHABET[RANDOM.nextInt(ALPHABET.length)];
        return new String(out);
    }

    public static String prefixed(String prefix) { return prefix + "_" + shortId(); }
}
